import{_ as t,a,o,a6 as d}from"./chunks/framework.CJDy2q7X.js";const p=JSON.parse(`{"title":"List GDPR Requests","description":"","frontmatter":{"outline":false,"examples":[{"id":"list-gdpr-requests","title":"List Own GDPR Requests","description":"Retrieve a paginated list of the authenticated customer's own GDPR data requests, newest first.","request":"GET /api/shop/gdpr-requests?sort=id&order=desc\\nContent-Type: application/json\\nX-STOREFRONT-KEY: pk_storefront_PvlE42nWGsKRVIf8bDlJngTPAdWAZbIy\\nAuthorization: Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9...\\n","response":"HTTP/1.1 200 OK\\nX-Total-Count: 1\\nX-Page: 1\\nX-Per-Page: 30\\nX-Total-Pages: 1\\n\\n[\\n  {\\n    \\"id\\": 12,\\n    \\"email\\": \\"jane@example.com\\",\\n    \\"status\\": \\"pending\\",\\n    \\"type\\": \\"delete\\",\\n    \\"message\\": \\"Please delete my account data.\\",\\n    \\"revokedAt\\": null,\\n    \\"createdAt\\": \\"2026-06-25T10:30:00+05:30\\",\\n    \\"updatedAt\\": \\"2026-06-25T10:30:00+05:30\\",\\n    \\"successMessage\\": null,\\n    \\"customer\\": \\"/api/shop/customers/7\\"\\n  }\\n]\\n","commonErrors":[{"error":"400 Bad Request","cause":"GDPR data requests are turned off in the store's admin configuration","solution":"Re-enable GDPR from the admin configuration before calling this endpoint"},{"error":"403 Forbidden","cause":"Missing or invalid customer Bearer token","solution":"Log in and provide a valid customer authentication token"},{"error":"401 Unauthorized","cause":"Storefront key is missing or invalid","solution":"Provide a valid X-STOREFRONT-KEY header"}]}]},"headers":[],"relativePath":"api/rest-api/shop/gdpr-requests/list-gdpr-requests.md","filePath":"api/rest-api/shop/gdpr-requests/list-gdpr-requests.md","lastUpdated":1787290888000}`),s={name:"api/rest-api/shop/gdpr-requests/list-gdpr-requests.md"};function r(n,e,i,c,h,l){return o(),a("div",null,e[0]||(e[0]=[d('<h1 id="list-gdpr-requests" tabindex="-1">List GDPR Requests <a class="header-anchor" href="#list-gdpr-requests" aria-label="Permalink to &quot;List GDPR Requests&quot;">​</a></h1><p>Retrieve a paginated list of the authenticated customer&#39;s <strong>own</strong> GDPR data requests. Requests are always scoped to the logged-in customer — a customer can never see another customer&#39;s requests. Results are ordered newest first by default.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/shop/gdpr-requests</span></span></code></pre></div><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>This endpoint requires an authenticated customer — send the storefront key and a customer Bearer token. See the <a href="/api/rest-api/authentication.html">Authentication</a> page.</p><h2 id="gdpr-must-be-enabled" tabindex="-1">GDPR must be enabled <a class="header-anchor" href="#gdpr-must-be-enabled" aria-label="Permalink to &quot;GDPR must be enabled&quot;">​</a></h2><p>If GDPR data requests are disabled in the store&#39;s admin configuration, the endpoint returns <strong>HTTP 400</strong> with the message <strong>&quot;GDPR data requests are disabled. Please enable GDPR from the admin configuration.&quot;</strong> The feature has been turned off on the admin side.</p><h2 id="request-headers" tabindex="-1">Request Headers <a class="header-anchor" href="#request-headers" aria-label="Permalink to &quot;Request Headers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Header</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>Content-Type</code></td><td>Yes</td><td>application/json</td></tr><tr><td><code>X-STOREFRONT-KEY</code></td><td>Yes</td><td>Your storefront API key</td></tr><tr><td><code>Authorization</code></td><td>Yes</td><td>Bearer token (customer login required)</td></tr></tbody></table><h2 id="query-parameters" tabindex="-1">Query Parameters <a class="header-anchor" href="#query-parameters" aria-label="Permalink to &quot;Query Parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>sort</code></td><td>string</td><td><code>id</code></td><td>Sort column — <code>id</code> or <code>created_at</code>.</td></tr><tr><td><code>order</code></td><td>string</td><td><code>desc</code></td><td>Sort direction — <code>asc</code> or <code>desc</code>.</td></tr></tbody></table><p>The page size is fixed at 30 and cannot be changed; <code>page</code> and <code>per_page</code> are accepted by the URL but do not affect the result. Read the totals from the response headers.</p><h2 id="response-fields-200-ok" tabindex="-1">Response Fields (200 OK) <a class="header-anchor" href="#response-fields-200-ok" aria-label="Permalink to &quot;Response Fields (200 OK)&quot;">​</a></h2><p>A bare JSON array of the customer&#39;s own requests. There is no <code>data</code> wrapper and no <code>meta</code> block — pagination is reported in the <code>X-Total-Count</code>, <code>X-Page</code>, <code>X-Per-Page</code>, and <code>X-Total-Pages</code> headers.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Request ID. Use it on <a href="/api/rest-api/shop/gdpr-requests/view-gdpr-request.html">View</a>, <a href="/api/rest-api/shop/gdpr-requests/revoke-gdpr-request.html">Revoke</a>, and <a href="/api/rest-api/shop/gdpr-requests/delete-gdpr-request.html">Delete</a>.</td></tr><tr><td><code>email</code></td><td>string</td><td>Email address tied to the request.</td></tr><tr><td><code>status</code></td><td>string</td><td><code>pending</code>, <code>processing</code>, <code>declined</code>, <code>approved</code>, or <code>revoked</code>.</td></tr><tr><td><code>type</code></td><td>string</td><td><code>delete</code> or <code>update</code>.</td></tr><tr><td><code>message</code></td><td>string</td><td>The customer&#39;s own description of the request.</td></tr><tr><td><code>revokedAt</code></td><td>string</td><td>Timestamp of the revocation, <code>null</code> while the request is live. Note this one is a plain date-time, not the ISO 8601 form the other two use.</td></tr><tr><td><code>createdAt</code> / <code>updatedAt</code></td><td>string</td><td>ISO 8601 timestamps.</td></tr><tr><td><code>successMessage</code></td><td>string</td><td>Populated only on a write response — always <code>null</code> when listing.</td></tr><tr><td><code>customer</code></td><td>string</td><td>Path of the owning customer, e.g. <code>/api/shop/customers/7</code>. Not a nested object.</td></tr></tbody></table><h2 id="empty-collection" tabindex="-1">Empty Collection <a class="header-anchor" href="#empty-collection" aria-label="Permalink to &quot;Empty Collection&quot;">​</a></h2><p>A customer who has raised nothing gets <code>200</code> with <code>[]</code> and <code>X-Total-Count: 0</code>.</p><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><ul><li><strong>&quot;My data requests&quot; screen</strong> — list the customer&#39;s requests and offer Revoke on any that are still <code>pending</code> or <code>processing</code>.</li><li><strong>Prevent duplicate submissions</strong> — check for an open request before showing the raise form again; the API does not reject a second one.</li></ul><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ul><li><strong>Read the count from <code>X-Total-Count</code></strong> — there is no <code>meta</code> block, and the array is one fixed page of 30.</li><li><strong>Handle the <code>400</code> disabled error before rendering the screen</strong> — with GDPR switched off in the admin panel, every endpoint in this menu fails the same way, so the whole section should be hidden.</li><li><strong>Show Revoke only for <code>pending</code> and <code>processing</code></strong> — the endpoint rejects any other status with <code>422</code>.</li></ul><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/rest-api/shop/gdpr-requests/view-gdpr-request.html">View GDPR Request</a> — one request by id</li><li><a href="/api/rest-api/shop/gdpr-requests/create-gdpr-request.html">Raise a GDPR Request</a> — raise a delete or update request</li><li><a href="/api/rest-api/shop/gdpr-requests/">GDPR Requests Overview</a> — the GDPR menu overview, including the setting that gates it</li></ul>',24)]))}const g=t(s,[["render",r]]);export{p as __pageData,g as default};
